const t={knownGoodPack:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Chụp ảnh cấu hình máy in đang hoạt động thành một gói để bạn có thể khôi phục sau khi chỉnh sửa sai."}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Hủy"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Chưa có gói nào. Hãy tạo một gói khi máy in đang được cấu hình đúng như bạn muốn."}},files:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" tệp cấu hình"}]}},create:{label:{t:0,b:{t:2,i:[{t:3}],s:"Gói mới"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"vd: SV08 hoạt động tốt - trước khi tinh chỉnh"}},button:{t:0,b:{t:2,i:[{t:3}],s:"Tạo gói"}}},restore:{button:{t:0,b:{t:2,i:[{t:3}],s:"Khôi phục"}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Ghi đè cấu hình hiện tại bằng gói này?"}},note:{t:0,b:{t:2,i:[{t:3}],s:"Khôi phục sẽ ghi đè các tệp cấu hình của bạn; hãy khởi động lại Klipper sau đó để áp dụng."}},restored:{t:0,b:{t:2,i:[{t:3,v:"Đã khôi phục "},{t:4,k:"count"},{t:3,v:" tệp cấu hình - khởi động lại Klipper để áp dụng"}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Máy in đang bận - không thể khôi phục lúc này"}},not_found:{t:0,b:{t:2,i:[{t:3}],s:"Thiếu các tệp của gói"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Gói này không có tệp nào"}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:"Không thể khôi phục: "},{t:4,k:"error"}]}}},delete:{button:{t:0,b:{t:2,i:[{t:3}],s:"Xóa"}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Xóa gói"}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Hướng dẫn"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Hướng dẫn Gói Cấu hình Tốt"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Đóng"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Gói Cấu hình Tốt là gì?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Một ảnh chụp toàn bộ tệp cấu hình máy in (printer.cfg và các tệp được include) được lưu thành một gói có tên. Khi máy in của bạn in tốt, hãy chụp một gói để có thể quay lại nếu một chỉnh sửa sau này làm hỏng thứ gì đó."}}},restore:{title:{t:0,b:{t:2,i:[{t:3}],s:"Khôi phục một gói"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Khôi phục sẽ ghi các tệp của gói đè lên cấu hình hiện tại. Thao tác này bị từ chối khi máy in đang bận, và bạn phải khởi động lại Klipper sau đó để cấu hình đã khôi phục có hiệu lực."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Thuật ngữ"}}}},glossary:{configPack:{term:{t:0,b:{t:2,i:[{t:3}],s:"Gói cấu hình"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Một bộ đã lưu gồm tất cả tệp cấu hình máy in của bạn tại một thời điểm."}}},restorePoint:{term:{t:0,b:{t:2,i:[{t:3}],s:"Điểm khôi phục"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Một trạng thái tốt đã biết mà bạn có thể quay lại - ở đây là một gói được chụp khi máy in đang hoạt động."}}}}}}};export{t as default};
